cd /tmp/claude-1000/-home-yamal-projects-almanac/aa1cb92c-f3e8-40ca-88a0-fe292dbd0474/scratchpad/agents/cofid && cat > profile.py <<'EOF'
import openpyxl, collections, re
RAW = "/home/yamal/ALManac-food-data/raw/cofid/2021/"
for name in ["McCance_Widdowsons_Composition_of_Foods_Integrated_Dataset_2021.xlsx", "CoFID_oldFoods.xlsx"]:
    wb = openpyxl.load_workbook(RAW + name, read_only=True, data_only=True)
    types = collections.Counter()
    odd = collections.Counter()
    widths = {}
    for ws in wb.worksheets:
        rows = list(ws.iter_rows(values_only=True))
        widths[ws.title] = (len(rows), collections.Counter(len(r) for r in rows))
        for r in rows:
            for c in r:
                types[type(c).__name__] += 1
                if isinstance(c, str) and c != c.strip():
                    odd["untrimmed str"] += 1
                if isinstance(c, str) and ("\n" in c or "\r" in c):
                    odd["newline str"] += 1
                if isinstance(c, str) and c == "":
                    odd["empty str"] += 1
                if isinstance(c, str) and c.strip() == "" and c != "":
                    odd["whitespace-only str"] += 1
                if isinstance(c, float) and c.is_integer():
                    odd["integral float"] += 1
    print("==", name, dict(types), dict(odd))
    for t, w in widths.items():
        print("  ", repr(t), w)
    wb.close()
EOF
python3 profile.py

