input.command:
cd /tmp/claude-1000/-home-yamal-projects-almanac/aa1cb92c-f3e8-40ca-88a0-fe292dbd0474/scratchpad/agents/cofid && cat > profile3.py <<'EOF'
import openpyxl, re
RAW = "/home/yamal/ALManac-food-data/raw/cofid/2021/"
wb = openpyxl.load_workbook(RAW + "McCance_Widdowsons_Composition_of_Foods_Integrated_Dataset_2021.xlsx", read_only=True, data_only=True)
rows = list(wb["1.3 Proximates"].iter_rows(values_only=True))
idx = {c: i for i, c in enumerate(rows[1]) if c is not None}
data = list(enumerate(rows[3:], start=4))
def v(r, k): return r[idx[k]]
print("== Q groups")
for n, r in data:
    if r[3].startswith("Q"):
        print(n, r[0], r[3], repr(r[1]), "| KCALS", v(r,"KCALS"), "ALCO", v(r,"ALCO"), "WATER", v(r,"WATER"), "| desc:", (r[2] or "")[:70])
print("== BTM / single-letter groups")
for n, r in data:
    if r[3] in ("BTM","Q","P","A","D","F","G","H","J","S"):
        print(n, r[0], r[3], repr(r[1]))
print("== alcohol > 0 outside Q")
for n, r in data:
    a = v(r, "ALCO")
    if r[3].startswith("Q") or a is None: continue
    s = str(a).strip()
    if s in ("", "0", "0.0", "0.00"): continue
    print(n, r[0], r[3], repr(r[1]), "ALCO", repr(a))
print("== drink-like names outside Q")
pat = re.compile(r"\b(beer|lager|ale|stout|cider|perry|wine|sherry|port|vermouth|liqueur|spirit|spirits|brandy|gin|rum|vodka|whisky|whiskey|shandy|alcopop|cocktail|punch|pimms|mulled|alcohol)\b", re.I)
for n, r in data:
    if not r[3].startswith("Q") and pat.search(r[1]):
        print(n, r[0], r[3], repr(r[1]))
print("== blank KCALS / CHO rows")
for n, r in data:
    for k in ("KCALS", "CHO"):
        if v(r, k) is None:
            print(n, r[0], r[3], repr(r[1]), k, "blank")
EOF
python3 profile3.py

